// 1. Traemos la configuración y lo que pidió el usuario
const request = $('Build Advisor Request').first().json.advisor_request;
const config = $('Load M3 Config').first().json;

// 2. Traemos los productos de Qdrant (Nodo 5) de forma segura
let catalogItems = [];
try {
    // Busca los resultados, si vienen dentro de 'metadata' o en la raíz
    catalogItems = $('Retrieve Catalog Context').all().map(item => item.json.metadata || item.json);
} catch (e) {
    // Si no encontró nada, no pasa nada, se queda vacío
}

// 3. Traemos el conocimiento de Qdrant (Nodo 6) de forma segura
let knowledgeItems = [];
try {
    knowledgeItems = $('Retrieve Knowledge Context').all().map(item => item.json.metadata || item.json);
} catch (e) {}

// 4. Formateamos el catálogo en texto fácil de leer para la IA
let catalogText = "No se encontraron productos relevantes en el catálogo para esta consulta.";
if (catalogItems.length > 0) {
    catalogText = catalogItems.map(item => 
        `- Producto: ${item.titulo || item.name || 'Sin nombre'}\n  Precio: $${item.precio || item.price || 'N/A'}\n  Stock: ${item.stock || 'Consultar'}\n  Desc: ${item.descripcion || item.description || 'Sin descripción'}`
    ).join('\n\n');
}

// 5. Formateamos el conocimiento (FAQs) en texto para la IA
let knowledgeText = "No se requiere información adicional de políticas para esta consulta.";
if (knowledgeItems.length > 0) {
    knowledgeText = knowledgeItems.map(item => 
        `- Info: ${item.respuesta || item.contenido || item.pageContent || item.text || 'Dato interno'}`
    ).join('\n\n');
}

// 6. Construimos el mega-contexto final y se lo mandamos a la IA
return {
    json: {
        advisor_context: {
            user_intent: request.intent,
            mode: request.mode,
            commercial_stage: request.commercial_stage,
            user_message: request.user_message,
            extracted_entities: {
                product: request.product_candidate,
                category: request.category_candidate,
                city: request.city
            },
            available_catalog: catalogText,
            business_knowledge: knowledgeText,
            system_config: config
        }
    }
};

return {
  json: {
    advisor_request: {
      mode: "recommendation",
      user_message: "busco una silla para mi bebé",
      intent: "product_search",
      commercial_stage: "consideration",
      category_candidate: "silla",
      product_candidate: null,
      preference: null,
      city: null,
      quantity: null
    }
  }
};
